    'RegistrationText'=>'Kayıtlı SimpleRisk örneklerine, Yükseltme ve Güvenli Kontrol Çerçevesi (SCF) Ekstralarına anında erişim verilir. Yükseltme Ekstrası, SimpleRisk bulut sunucunuzu bir düğmeyi tıklatarak yedeklemenizi ve yükseltmenizi sağlar. Secure Controls Framework (SCF) Extra, SimpleRisk Governance işlevine entegre edilmiş ortak bir denetim çerçevesi sağlar. SimpleRisk\'e kaydolduktan sonra, kayıt bilgileriniz SimpleRisk tarafından barındırılan bir sunucuya gönderilecektir. Sağlanan kayıt bilgileri, SimpleRisk tarafından müşterileri yeni sürümler ve güvenlik güncellemelerinden haberdar etmek için kullanılacaktır. SimpleRisk\'e kaydolma işlemi sizi pazarlama iletişimlerimize dahil edecektir, ancak bu iletişimlerdeki abonelikten çıkma bağlantısını kullanarak istediğiniz zaman bu seçeneği iptal edebilirsiniz. SimpleRisk, müşterilerimizin mahremiyetine saygı duyar ve SimpleRisk kayıt işlemi aracılığıyla bize sağlanan bilgiler asla üçüncü şahıslara satılmaz.',
